public List<TimeRange> buildTimeRanges(long start, long end) {
    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Duration exceeds maximum fetch data duration");
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    long remainingTime = duration;
    while (remainingTime > 0) {
        long rangeStart = start + (duration - remainingTime);
        long rangeEnd = start + (duration - remainingTime) + FETCH_DATA_DURATION;
        if (rangeEnd > end) {
            rangeEnd = end;
        }
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
        remainingTime -= FETCH_DATA_DURATION;
    }
    return timeRanges;
}

