static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1 || dayStep > 31) {
      throw new IllegalArgumentException("Invalid day step value");
    }
    if (timeBucket < 0) {
      throw new IllegalArgumentException("Invalid time bucket value");
    }
    int year = (int) (timeBucket / Math.pow(10, 4));
    int month = (int) (timeBucket / Math.pow(10, 2) % 100);
    int day = (int) (timeBucket % 100);
    day -= dayStep;
    if (day < 1) {
      month -= 1;
      if (month <= 0) {
        year -= 1;
        month = 12;
      }
      day += getDaysInMonth(year, month);
    }
    if (day > getDaysInMonth(year, month)) {
      day = getDaysInMonth(year, month);
    }
    return (long) (year * Math.pow(10, 4) + month * Math.pow(10, 2) + day);
  }

  private int getDaysInMonth(int year, int month) {
    int[] monthDays = new int[] { 31, 28, 31, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month != 2 || (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
      return monthDays[month - 1];
    } else {
      return monthDays[month - 1] - 1;
    }
  }

