private void pop(String descriptor) {
    if (descriptor.charAt(0) == '(') {
        // Method descriptor, pop arguments first
        String arguments = descriptor.substring(1, descriptor.length() - 1);
        for (String argument : arguments.split(",")) {
            pop(argument);
        }
    }
    // Pop the return type
    descriptor = descriptor.substring(1);
    popStack(descriptor);
}

// Pop a type from the output frame stack
private void popStack(String type) {
    if (type.charAt(0) == 'L' && type.endsWith(";")) {
        // Object type, pop one object
        writer.write(Integer.valueOf(0x07));
    } else if (type.equals("I") || type.equals("S")) {
        // Integer type, pop 4 bytes
        writer.write(Integer.valueOf(0x03));
    } else if (type.equals("B")) {
        // Byte type, pop 1 byte
        writer.write(Integer.valueOf(0x00));
    } else if (type.equals("J")) {
        // Long type, pop 8 bytes
        writer.write(Integer.valueOf(0x08));
    } else {
        // Unknown type, throw exception
        throw new IllegalStateException("Cannot pop type " + type);
    }
}
