            break;
        case 'L':
            // Case when the descriptor describes a type
            // Pop the type from the stack
            pop(descriptor.substring(1));
            break;
        default:
            // Error: invalid descriptor
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}
