public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        // validate input parameters
        if (file == null || timeRanges == null || timeRanges.size() == 0) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // parse thread snapshots from the file
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] columns = line.split(",");
                if (columns.length >= 3) {
                    String threadName = columns[0];
                    String eventName = columns[1];
                    long timestamp = Long.parseLong(columns[2]);

                    // check if the timestamp falls within the specified time range
                    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                        if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                            // add the thread snapshot to the list
                            ThreadSnapshot snapshot = new ThreadSnapshot(threadName, eventName, timestamp);
                            threadSnapshots.add(snapshot);
                            break;
                        }
                    }
                }
            }
        } catch (IOException e) {
            throw new IOException("Error reading from file", e);
        }

        return threadSnapshots;
    }
}
